const WGENERAL={"guf":[["נשימה בוקר וערב","חמש נשימות עמוקות בבוקר ובערב. שאיפה דרך האף, נשיפה איטית."],["שיחה עם האיבר","אחרי כמה נשימות, הניחו יד על המקום שכואב ושאלו אותו בשקט: מה אתה צריך? מה אתה מנסה לומר לי? לא לחשוב על התשובה, אלא לחכות ולראות מה עולה."]],"regesh":[["שלוש שאלות על רגע אחד","בחרו רגע מהיום שבו כעסתם, פחדתם או נסגרתם. כתבו: מה הרגשתי בגוף, מה חשבתי, ומה עשיתי."],["מכתב לעצמי","כתבו לעצמכם מכתב, כמו שהייתם כותבים לחבר טוב שעובר תקופה קשה."],["דו שיח בין השכל ללב","בחרו נושא שמטריד אתכם. כתבו מה השכל אומר עליו ומה הלב אומר, בתורות, כמו שיחה. בלי לתכנן, לתת לזה לזרום."]],"machshava":[["להחליף משפט ישן","זהו משפט שלילי אחד שחוזר אצלכם. כתבו לידו משפט חדש שאתם רוצים להאמין בו, ואמרו אותו לעצמכם כל בוקר במשך השבוע."],["מה זה בא ללמד אותי","כתבו בלי צנזורה מה הקושי או המחלה אולי באים ללמד אתכם. אין תשובה נכונה, רק מה שעולה."]],"ratzon":[["עוד שלושה חודשים","עצמו עיניים ודמיינו את עצמכם בעוד שלושה חודשים. איך הגוף מרגיש, איך נראה היום שלכם, מה השתנה. בפרטים ובצבעים."],["הכישרונות שלי","כתבו מה הכישרונות שאיתם הגעתם לעולם, ואחר כך שאלו: איך אני יכול או יכולה להשתמש בהם כדי להאיר גם לאחרים?"]]};

